// ✅ ChatSidebar.js
import React, { useState, useEffect } from "react";
import axios from "axios";
import "../styles/ChatSide.css";

const ChatSidebar = ({ onConversationSelect, currentUser, conversations, setConversations }) => {
  const [searchTerm, setSearchTerm] = useState("");
  const [searchResults, setSearchResults] = useState([]);

  useEffect(() => {
    console.log("Logged-in user from localStorage:", currentUser);
  }, [currentUser]);

  const handleSearch = async () => {
    if (!searchTerm.trim()) return;

    try {
      console.log("🔍 Searching by username with keywords:", searchTerm);
      const res = await axios.get(`/api/profile/search?username=${searchTerm}`, {
        headers: {
          Authorization: `Bearer ${localStorage.getItem("token")}`,
        },
      });

      const users = res.data.map((profile) => profile.userId);
      console.log("🔎 # of users found:", users.length);
      setSearchResults(users);
    } catch (error) {
      console.error("❌ Error searching users:", error);
    }
  };

  const handleStartConversation = async (user) => {
    try {
      const res = await axios.post(
        "/api/conversations",
        { participantIds: [currentUser._id, user._id] },
        {
          headers: {
            Authorization: `Bearer ${localStorage.getItem("token")}`,
          },
        }
      );

      const conversation = res.data;
      setConversations((prev) => [conversation, ...prev]);
      onConversationSelect(conversation);
      setSearchResults([]);
      setSearchTerm("");
    } catch (error) {
      console.error("❌ Error starting conversation:", error);
    }
  };

  return (
    <div className="chat-sidebar">
      <h4 className="sidebar-title">Messages</h4>

      <input
        type="text"
        value={searchTerm}
        onChange={(e) => setSearchTerm(e.target.value)}
        placeholder="Search by username"
      />
      <button className="search-button" onClick={handleSearch}>Search</button>

      {searchResults.map((user) => (
        <div
          key={user._id}
          className="search-result"
          onClick={() => handleStartConversation(user)}
        >
          {user.username}
        </div>
      ))}

      <div className="conversations">
        {conversations.length === 0 ? (
          <p className="no-convo">No conversations found.</p>
        ) : (
          conversations.map((conv) => (
            <div key={conv._id} className="conversation-item" onClick={() => onConversationSelect(conv)}>
              {conv.participants
                .filter((p) => p._id !== currentUser._id)
                .map((user) => user.username)
                .join(", ")}
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default ChatSidebar;
